import { Component, inject, OnInit, signal } from '@angular/core';
import { ReactiveFormsModule, FormBuilder, Validators } from '@angular/forms';
import { NgIf, NgFor } from '@angular/common';
import { WalletApiService } from '../../core/services/wallet-api.service';
import { ToastService } from '../../shared/components/toast.service';
import { Wallet } from '../../core/services/wallet.models';
import { XofPipe } from '../../shared/pipes/xof.pipe';
import { PhonePipe } from '../../shared/pipes/phone.pipe';
import { phoneValidator } from '../../shared/validators/phone.validators';

@Component({
  selector: 'app-wallets-admin',
  standalone: true,
  imports: [ReactiveFormsModule, NgIf, NgFor, XofPipe, PhonePipe],
  templateUrl: './wallets-admin.component.html',
  styleUrls: ['./wallets-admin.component.css'],
})
export class WalletsAdminComponent implements OnInit {
  private readonly walletApi = inject(WalletApiService);
  private readonly toast = inject(ToastService);
  private readonly fb = inject(FormBuilder);

  readonly wallets = signal<Wallet[]>([]);
  readonly page = signal(0);
  readonly totalPages = signal(1);
  readonly found = signal<Wallet | null>(null);
  readonly searchPhone = signal('');

  readonly depositForm  = this.fb.group({ amount: [null as number | null, [Validators.required, Validators.min(1)]] });
  readonly withdrawForm = this.fb.group({ amount: [null as number | null, [Validators.required, Validators.min(1)]] });
  readonly createForm   = this.fb.group({
    ownerName: ['', Validators.required],
    phone: ['', [Validators.required, phoneValidator()]],
  });

  ngOnInit(): void { this.load(); }

  private load(): void {
    this.walletApi.getAll(this.page(), 10).subscribe(res => {
      this.wallets.set(res.content);
      this.totalPages.set(res.totalPages);
    });
  }

  search(): void {
    if (!this.searchPhone()) return;
    this.walletApi.getByPhone(this.searchPhone()).subscribe({
      next: w => this.found.set(w),
      error: () => this.found.set(null),
    });
  }

  deposit(id: number): void {
    const { amount } = this.depositForm.value;
    this.walletApi.deposit(id, { amount: amount! }).subscribe(() => {
      this.toast.success('Depot effectue.');
      this.depositForm.reset();
      this.search();
    });
  }

  withdraw(phone: string): void {
    const { amount } = this.withdrawForm.value;
    this.walletApi.withdraw({ phone, amount: amount! }).subscribe(() => {
      this.toast.success('Retrait effectue.');
      this.withdrawForm.reset();
      this.search();
    });
  }

  createWallet(): void {
    const { ownerName, phone } = this.createForm.value;
    this.walletApi.create({ ownerName: ownerName ?? '', phone: phone ?? '' }).subscribe(() => {
      this.toast.success('Portefeuille cree.');
      this.createForm.reset();
      this.load();
    });
  }

  prevPage(): void { this.page.update(p => p - 1); this.load(); }
  nextPage(): void { this.page.update(p => p + 1); this.load(); }
}

<div class="page">
  <h1>Gestion des portefeuilles</h1>
  <div class="search-bar">
    <input [value]="searchPhone()" (input)="searchPhone.set($any($event.target).value)" placeholder="Rechercher par telephone..." />
    <button (click)="search()" class="btn">Rechercher</button>
  </div>
  <div class="card" *ngIf="found()">
    <p><strong>Nom :</strong> {{ found()!.ownerName }}</p>
    <p><strong>Tel :</strong> {{ found()!.phone | phone }}</p>
    <p><strong>Solde :</strong> {{ found()!.balance | xof }}</p>
    <div class="ops">
      <form [formGroup]="depositForm" (ngSubmit)="deposit(found()!.id)" class="op-form">
        <input type="number" formControlName="amount" placeholder="Depot" />
        <button type="submit" class="btn green">Deposer</button>
      </form>
      <form [formGroup]="withdrawForm" (ngSubmit)="withdraw(found()!.phone)" class="op-form">
        <input type="number" formControlName="amount" placeholder="Retrait" />
        <button type="submit" class="btn red">Retirer</button>
      </form>
    </div>
  </div>
  <details class="create-section">
    <summary>Creer un portefeuille</summary>
    <form [formGroup]="createForm" (ngSubmit)="createWallet()" class="card create-form">
      <div class="field">
        <label>Nom complet</label>
        <input formControlName="ownerName" placeholder="Prenom Nom" />
      </div>
      <div class="field">
        <label>Telephone</label>
        <input formControlName="phone" placeholder="77 XXX XX XX" />
        <span class="err" *ngIf="createForm.get('phone')?.touched && createForm.get('phone')?.hasError('invalidPhone')">Numero invalide.</span>
      </div>
      <button type="submit" [disabled]="createForm.invalid" class="btn">Creer</button>
    </form>
  </details>
  <table class="wallet-table">
    <thead>
      <tr><th>Telephone</th><th>Nom</th><th>Solde</th><th>Cree le</th></tr>
    </thead>
    <tbody>
      <tr *ngFor="let w of wallets()">
        <td>{{ w.phone | phone }}</td>
        <td>{{ w.ownerName }}</td>
        <td>{{ w.balance | xof }}</td>
        <td>{{ w.createdAt }}</td>
      </tr>
      <tr *ngIf="wallets().length === 0">
        <td colspan="4" class="empty">Aucun portefeuille.</td>
      </tr>
    </tbody>
  </table>
  <div class="pagination">
    <button (click)="prevPage()" [disabled]="page() === 0">Precedent</button>
    <span>Page {{ page() + 1 }} / {{ totalPages() }}</span>
    <button (click)="nextPage()" [disabled]="page() >= totalPages() - 1">Suivant</button>
  </div>
</div>
